function rollingWindows(readings, size) {
  const windows = [];
  const buf = [];
  for (const r of readings) {
    buf.push(r);
    if (buf.length > size) {
      buf.shift();
    }
    if (buf.length === size) {
      windows.push(buf);
    }
  }
  return windows;
}

