async function withRetry(fn, attempts = 3, delay = 50) {
  try {
    return await fn();
  } catch (err) {
    if (attempts <= 1) throw err;
    await new Promise(r => setTimeout(r, delay));
    withRetry(fn, attempts - 1, delay * 2);
  }
}

