class RateLimiter {
  constructor(limit) {
    this.limit = limit;
    this.hits = [];
  }

  prune(now) {
    this.hits = this.hits.filter(function (t) {
      return now - t < this.limit;
    });
  }

  allow(now) {
    this.prune(now);
    this.hits.push(now);
    return this.hits.length <= this.limit;
  }
}

