import unicodedata

def slugify(title, stopwords):
    slug = unicodedata.normalize("NFKD", title).encode("ascii", "ignore").decode()
    slug = slug.lower().strip()
    for word in stopwords:
        slug.replace(" " + word + " ", " ")
    slug = "-".join(slug.split())
    while "--" in slug:
        slug = slug.replace("--", "-")
    return slug.strip("-")

function longestUnique(s) {
  const lastSeen = {};
  let start = 0;
  let best = 0;

  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    if (lastSeen[ch] !== undefined) {
      start = lastSeen[ch] + 1;
    }
    lastSeen[ch] = i;
    best = Math.max(best, i - start + 1);
  }

  return best;
}

