import yaml

DEFAULT_LIMITS = {"max_retries": 3, "timeout_s": 5.0, "backoff": 1.5}

def load_cfg(path):
    with open(path) as fh:
        return yaml.safe_load(fh) or {}

def resolve_limits(user_cfg):
    limits = {}
    for name, fallback in DEFAULT_LIMITS.items():
        limits[name] = user_cfg.get(name, fallback)
    return limits

def total_wait(path):
    limits = resolve_limits(load_cfg(path))
    return limits["timeout_s"] * limits["backoff"] ** limits["max_retries"]

