class Uploader {
  constructor(file, cache) {
    this.handlers = {};
    this.begin(file, cache);
  }
  on(event, fn) {
    (this.handlers[event] = this.handlers[event] || []).push(fn);
    return this;
  }
  emit(event, payload) {
    (this.handlers[event] || []).forEach(fn => fn(payload));
  }
  begin(file, cache) {
    const hit = cache.get(file.hash);
    if (hit) return this.emit('done', hit.url);
    postFile(file).then(res => this.emit('done', res.url));
  }
}

